 insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r32-v2','0.2.0','Lesson 6 step 5 of 6: Who says what?','reading','guided_practice','Read LEARN FIRST and the worked example. Then choose the group that holds or does each thing.','The group named next to a view is not always the group that holds it. Find who is saying it: note, caution, contend, argue, warn.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "Paragraph D: who chooses the thin mats of drought-tolerant sedum?", "accepted_answers": ["B"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "options": [{"value": "A", "label": "A  ecologists"}, {"value": "B", "label": "B  developers"}, {"value": "C", "label": "C  engineers"}, {"value": "D", "label": "D  property owners"}]}, {"id": "q2", "prompt": "Paragraph D: who criticises the thin mats of sedum?", "accepted_answers": ["C"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "options": [{"value": "A", "label": "A  developers"}, {"value": "B", "label": "B  engineers"}, {"value": "C", "label": "C  ecologists"}, {"value": "D", "label": "D  urban planners"}]}, {"id": "q3", "prompt": "Paragraph E: who says that they pay while the public gains?", "accepted_answers": ["D"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "options": [{"value": "A", "label": "A  municipalities"}, {"value": "B", "label": "B  the wider public"}, {"value": "C", "label": "C  urban planners"}, {"value": "D", "label": "D  property owners"}]}, {"id": "q4", "prompt": "Paragraph E: who responds by offering subsidies?", "accepted_answers": ["A"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "options": [{"value": "A", "label": "A  municipalities"}, {"value": "B", "label": "B  property owners"}, {"value": "C", "label": "C  epidemiologists"}, {"value": "D", "label": "D  developers"}]}, {"id": "q5", "prompt": "Paragraph D: which word shows that the engineers hold a view?", "accepted_answers": ["B"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "options": [{"value": "A", "label": "A  caution"}, {"value": "B", "label": "B  note"}, {"value": "C", "label": "C  contend"}, {"value": "D", "label": "D  warn"}]}, {"id": "q6", "prompt": "Paragraph B: who argues that warm nights make people less able to cope with heat?", "accepted_answers": ["D"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "options": [{"value": "A", "label": "A  municipal authorities"}, {"value": "B", "label": "B  elderly residents"}, {"value": "C", "label": "C  engineers"}, {"value": "D", "label": "D  epidemiologists"}]}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 10, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "teacher_notes": "1 developers: the sedum is \"favoured by developers\". They choose it. The ecologists, named in the same sentence, criticise it.\n2 ecologists: \"Ecologists, for their part, caution that the thin mats ... sustain only a fraction of the insect and bird life\". Saying word: caution.\n3 property owners: \"Owners contend ... that while the wider public enjoys cooler streets, the financial burden falls entirely on them\". Saying word: contend. The wider public gains; it says nothing.\n4 municipalities: \"A number of municipalities have responded with subsidies\". They respond to the owners'' view; they do not hold it.\n5 note: \"Engineers note that a planted roof ... may keep its upper floors comfortable\". Caution belongs to the ecologists; contend to the owners; warn to the planners.\n6 epidemiologists: \"Epidemiologists ... arguing that bodies deprived of the chance to cool down overnight are less able to withstand the following day''s heat\". Elderly residents are the people at risk, not the speakers.\nRead each explanation, then find the proof in the passage yourself.", "focus": "Identify viewpoint: match a view or action to the group that holds it when other groups are named nearby."}'::jsonb || jsonb_build_object('passage', to_jsonb('LEARN FIRST: find who is SAYING it, not who is nearby

Several groups are often named close together. The group named next to a view is not always the group that holds it.
1. Circle every group of people in the paragraph.
2. Find each group''s saying or doing word: note, caution, contend, argue, warn, regard, respond.
3. Match the view to the group that says it.

WORKED EXAMPLE
"Paragraph B: who now treats lowering temperatures as a public health priority?"
Groups in B: epidemiologists, elderly residents, municipal authorities.
Epidemiologists study heatwaves and argue about bodies at night: that is a different view.
Elderly residents are the people at risk; they do not say anything.
"For municipal authorities, lowering urban temperatures has consequently become as much a public health priority as an energy one."
Answer: municipal authorities. The trap is the epidemiologists, the experts named in the same paragraph.' || '

